test:
for values,weights,expected in [(['only'],[1],'only'),(['a','b','c','d'],[0,2,0,0],'b'),(['a','b','c','d'],[0,0,0.125,0],'c')]:
    sampler=WeightedSampler(values,weights)
    assert all(sampler.sample()==expected for _ in range(100))

for values,weights in [([],[]),(['a'],[-1]),(['a'],[0]),(['a','b'],[2,-1])]:
    try:
        WeightedSampler(values,weights)
    except AssertionError:
        pass
    else:
        raise AssertionError('invalid configuration accepted')

for values,weights in [(['a','b'],[1]),(['a'],[1,2]),(['a'],[float('nan')]),(['a'],[float('inf')]),(['a','b'],[1e308,1e308])]:
    try:
        WeightedSampler(values,weights)
    except AssertionError:
        pass
    else:
        raise AssertionError('invalid configuration accepted')
